async function commitUpdate(userId, pref) {
  await db.begin();
  await db.run('UPDATE users SET pref=? WHERE id=?', pref, userId);
  await db.run('INSERT INTO outbox (user_id, event_type, payload, processed) VALUES (?,?,?,false)', userId, 'pref_updated', JSON.stringify({pref}));
